#include "common/benchmark.hpp"
#include "cfd/battery/lithium_ion.hpp"
#include <vector>
int main(int argc,char**argv){using namespace cfd::examples;const auto o=parse_options(argc,argv);auto cfg=cfd::battery::default_graphite_nmc_config();cfg.electrolyte.cells=o.quick?15U:60U*o.scale;cfg.negative.particle.radial_cells=o.quick?8U:32U;cfg.positive.particle.radial_cells=o.quick?8U:32U;Timer setup;cfd::battery::SingleParticleElectrolyteModel cell(cfg);const std::vector<cfd::battery::DriveCyclePoint> profile=o.quick?std::vector<cfd::battery::DriveCyclePoint>{{10,0.5},{5,0},{10,-0.25}}:std::vector<cfd::battery::DriveCyclePoint>{{600,0.5},{120,0},{300,-0.4},{120,0},{600,0.25}};const double setup_ms=setup.milliseconds();Timer sim;const auto result=cfd::battery::simulate_drive_cycle(cell,profile,o.quick?2.0:1.0);const double sim_ms=sim.milliseconds();const auto last=result.samples.back();const std::size_t dof=cfg.electrolyte.cells+cfg.negative.particle.radial_cells+cfg.positive.particle.radial_cells;emit({"phase16a_battery","spme_drive_cycle","cpu","state_steps",dof,result.samples.size(),setup_ms,sim_ms,double(dof)*double(result.samples.size()),last.terminal_voltage_v+last.temperature_k+result.discharged_capacity_ah});return 0;}
